create table public.financial_accounts(
 id uuid default gen_random_uuid() not null,
 org_id uuid not null,
 name text not null,
 account_type text not null,
 system_key text,
 currency text default 'UAH'::text not null,
 is_default bool default false not null,
 is_active bool default true not null,
 version int4 default 1 not null,
 created_by uuid,
 created_at timestamptz default now() not null,
 updated_at timestamptz default now() not null,
 constraint financial_accounts_account_type_check CHECK ((account_type = ANY (ARRAY['cash'::text, 'bank'::text, 'terminal'::text, 'safe'::text, 'other'::text]))),
 constraint financial_accounts_currency_check CHECK ((currency = ANY (ARRAY['UAH'::text, 'EUR'::text, 'USD'::text, 'GBP'::text, 'PLN'::text, 'CHF'::text]))),
 constraint financial_accounts_name_check CHECK (((char_length(TRIM(BOTH FROM name)) >= 1) AND (char_length(TRIM(BOTH FROM name)) <= 150))),
 constraint financial_accounts_org_id_fkey FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
 constraint financial_accounts_org_id_id_key UNIQUE (org_id, id),
 constraint financial_accounts_org_system_key_key UNIQUE (org_id, system_key),
 constraint financial_accounts_pkey PRIMARY KEY (id),
 constraint financial_accounts_system_key_check CHECK (((system_key IS NULL) OR (system_key = ANY (ARRAY['cash'::text, 'bank'::text, 'terminal'::text, 'safe'::text, 'other'::text])))),
 constraint financial_accounts_version_check CHECK ((version > 0))
);
create table public.stock_purchases(
 id uuid default gen_random_uuid() not null,
 org_id uuid not null,
 supplier_id uuid not null,
 purchase_number text not null,
 invoice_number text,
 status text default 'draft'::text not null,
