 total_amount numeric default 0 not null,
 paid_amount numeric default 0 not null,
 currency text default 'UAH'::text not null,
 document_url text,
 note text,
 created_by uuid,
 received_by uuid,
 created_at timestamptz default now() not null,
 updated_at timestamptz default now() not null,
 constraint stock_purchases_created_by_fkey FOREIGN KEY (created_by) REFERENCES clinic_users(id) ON DELETE SET NULL,
 constraint stock_purchases_currency_check CHECK ((currency = ANY (ARRAY['UAH'::text, 'EUR'::text, 'USD'::text, 'GBP'::text, 'PLN'::text, 'CHF'::text]))),
 constraint stock_purchases_dates_check CHECK (((expected_date IS NULL) OR (expected_date >= order_date))),
 constraint stock_purchases_discount_check CHECK (((discount_amount >= (0)::numeric) AND (discount_amount <= subtotal))),
 constraint stock_purchases_number_check CHECK (((length(TRIM(BOTH FROM purchase_number)) >= 1) AND (length(TRIM(BOTH FROM purchase_number)) <= 100))),
 constraint stock_purchases_org_id_fkey FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE CASCADE,
 constraint stock_purchases_paid_check CHECK (((paid_amount >= (0)::numeric) AND (paid_amount <= total_amount))),
 constraint stock_purchases_payment_status_check CHECK ((payment_status = ANY (ARRAY['unpaid'::text, 'partial'::text, 'paid'::text]))),
 constraint stock_purchases_pkey PRIMARY KEY (id),
 constraint stock_purchases_received_by_fkey FOREIGN KEY (received_by) REFERENCES clinic_users(id) ON DELETE SET NULL,
 constraint stock_purchases_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'ordered'::text, 'partially_received'::text, 'received'::text, 'cancelled'::text]))),
 constraint stock_purchases_subtotal_check CHECK ((subtotal >= (0)::numeric)),
 constraint stock_purchases_supplier_id_fkey FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
 constraint stock_purchases_total_check CHECK ((total_amount >= (0)::numeric))
);
