 constraint finance_transactions_source_check CHECK ((source = ANY (ARRAY['visit'::text, 'manual'::text, 'terminal'::text, 'stock'::text, 'salary'::text, 'other'::text]))),
 constraint finance_transactions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'cancelled'::text, 'failed'::text]))),
 constraint finance_transactions_type_check CHECK ((transaction_type = ANY (ARRAY['payment'::text, 'refund'::text, 'expense'::text, 'deposit'::text, 'withdrawal'::text]))),
